import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    while True:
        position = stream.tell()
        line = stream.readline()
        if not line:
            return {"columns": [], "rows": []}
        if line.strip() and not line.lstrip().startswith("#"):
            stream.seek(position)
            break

    reader = csv.reader(stream, delimiter=",", quotechar='"', doublequote=True)
    columns = next(reader, [])
    rows = []
    width = max(3, len(columns))

    for row in reader:
        rows.append(row)
        width = max(width, len(row))

    # Expand the schema rather than dropping fields from wider records.
    used = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used:
            columns.append(name)
            used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
